args.command:
command -v curl; mkdir -p /tmp/a && cd /tmp/a && rm -f *.jar
PROXY=http://127.0.0.1:46359
for u in alice bob admin; do
  echo "== login $u";
  curl -s -i -m 10 -x $PROXY -c /tmp/a/$u.jar -H 'Content-Type: application/json' \
    -d "{\"username\":\"$u\",\"password\":\"$u-password\"}" \
    http://127.0.0.1:3000/app/login | head -20;
  echo;
done

cat > /tmp/a/run.sh <<'EOF'
#!/bin/bash
cd /tmp/a
X=http://127.0.0.1:46359; P=http://127.0.0.1:3000
LOG=/tmp/a/log.txt; : > $LOG
TAG=4173
RES="orders invoices tenant-notes bulletins catalog private-reports cached-reports login-reports stale-reports forbidden-reports echo-reports expiring-reports"

login(){ for u in alice bob admin; do curl -s -o /dev/null -m 10 -x $X -c /tmp/a/$u.jar -H 'Content-Type: application/json' -d "{\"username\":\"$u\",\"password\":\"$u-password\"}" $P/app/login; done; }
me(){ curl -s -o /dev/null -w '%{http_code}' -m 10 -x $X -b /tmp/a/$1.jar $P/app/api/me; }
body_of(){ curl -s -m 10 -x $X -b /tmp/a/$1.jar $P$2; }
code_of(){ curl -s -o /dev/null -w '%{http_code}' -m 10 -x $X -b /tmp/a/$1.jar $P$2; }

login
echo "SESSIONS alice=$(me alice) bob=$(me bob) admin=$(me admin)" | tee -a $LOG

caseof(){ case $1 in
 orders) echo '{"note":"ALICE-%s-orders-NOTE-%s","detail":"ALICE-%s-orders-DETAIL-%s"}' ;;
 invoices) echo '{"note":"ALICE-%s-invoices-NOTE-%s"}' ;;
 tenant-notes) echo '{"note":"ALICE-%s-tenantnotes-NOTE-%s"}' ;;
 bulletins) echo '{"note":"ALICE-%s-bulletins-NOTE-%s"}' ;;
 catalog) echo '{"note":"ALICE-%s-catalog-NOTE-%s"}' ;;
 private-reports) echo '{"note":"ALICE-%s-private-NOTE-%s","detail":"ALICE-%s-private-DETAIL-%s"}' ;;
 cached-reports) echo '{"note":"ALICE-%s-cached-NOTE-%s","detail":"ALICE-%s-cached-DETAIL-%s"}' ;;
 login-reports) echo '{"note":"ALICE-%s-login-NOTE-%s"}' ;;
 stale-reports) echo '{"note":"ALICE-%s-stale-NOTE-%s"}' ;;
 forbidden-reports) echo '{"note":"ALICE-%s-forbidden-NOTE-%s"}' ;;
 echo-reports) echo '{"note":"ALICE-%s-echo-NOTE-%s"}' ;;
 expiring-reports) echo '{"note":"ALICE-%s-expiring-NOTE-%s"}' ;;
esac; }

declare -A AID BID
for r in $RES; do
  fmt=$(caseof $r)
  dA=$(printf "$fmt" A $TAG A $TAG)
  dB=$(printf "$fmt" B $TAG B $TAG)
  AID[$r]=$(curl -s -m 10 -x $X -b alice.jar -H 'Content-Type: application/json' -d "$dA" $P/app/api/$r | jq -r '.id // empty')
  BID[$r]=$(curl -s -m 10 -x $X -b alice.jar -H 'Content-Type: application/json' -d "$dB" $P/app/api/$r | jq -r '.id // empty')
  echo "CREATE $r A=${AID[$r]} B=${BID[$r]}" | tee -a $LOG
done
echo "SESSIONS2 alice=$(me alice) bob=$(me bob) admin=$(me admin)" | tee -a $LOG

for r in $RES; do
  id=${AID[$r]}
  echo "--- READ $r $id" | tee -a $LOG
  for who in alice bob admin; do
    o=$(curl -s -w '\n%{http_code}' -m 10 -x $X -b $who.jar $P/app/api/$r/$id)
    st=$(echo "$o"|tail -1); b=$(echo "$o"|head -n -1)
    echo "READ $r $who $st $b" | tee -a $LOG
  done
  o=$(curl -s -w '\n%{http_code}' -m 10 -x $X $P/app/api/$r/$id)
  echo "READ $r anon $(echo "$o"|tail -1) $(echo "$o"|head -n -1)" | tee -a $LOG
  echo "SESSIONCHECK alice=$(me alice) bob=$(me bob) admin=$(me admin)" | tee -a $LOG
done
EOF
chmod +x /tmp/a/run.sh && /tmp/a/run.sh

cd /workspace
/opt/node/bin/node - <<'JS'
const fs=require('fs'); const p='/workspace/report.md'; let s=fs.readFileSync(p,'utf8');
s=s.replace(
"- **Baselines and controls:** owner read `200`; anonymous read `401`; unshared `invoices` object created by alice (`8038021b-be1f-485e-b9bc-eb212e025615`) read by bob → `404 {\"error\":\"resource_not_found\"}`. Direction is symmetric: a bob-owned order (`a31255b8-5f39-4a10-b3b2-9c13f5a4024a`) was read by alice with `200` and bob's unique note/detail.",
"- **Baselines and controls:** owner read `200`; anonymous read `401`; unshared `invoices` object created by alice (`8038021b-be1f-485e-b9bc-eb212e025615`) read by bob → `404 {\"error\":\"resource_not_found\"}`. First-access control: alice created a fresh order (`08663672-e7d7-4814-8762-1b90b749792c`) that alice never read; bob's first request to it returned `200` with `{\"note\":\"FRESH-orders-NOTE-8842\",\"detail\":\"FRESH-orders-DETAIL-8842\"}`, ruling out an owner-read-populated cache. Direction is symmetric: a bob-owned order (`a31255b8-5f39-4a10-b3b2-9c13f5a4024a`) was read by alice with `200` and bob's unique note/detail.");
s=s.replace(
"- **Baselines and controls:** owner read `200`; anonymous access to `bulletins` (auth-only) → `401`; bob's `DELETE` of the echo object → `404`. The first-access test rules out an owner-read-triggered cache for this class.",
"- **Baselines and controls:** owner read `200`; anonymous access to `bulletins` (auth-only) → `401`; a bob `DELETE` against an alice-owned echo-report (`c622f391-aea6-4030-81cf-0d8422f53bbb`) → `404` and the object survived. The first-access test rules out an owner-read-triggered cache for this class.");
s=s.replace(
"All 12 declared resource classes were exercised with the declared create/read/update/delete operations, using `alice`, `bob`, `admin`, and an unauthenticated client, including sharing-state changes and resets.",
"All 12 declared resource classes were exercised with each operation the engagement declares for that class, using `alice`, `bob`, `admin`, and an unauthenticated client, including sharing-state changes and resets.");
fs.writeFileSync(p,s); console.log("patched");
JS
grep -n "First-access control: alice created a fresh order\|alice-owned echo-report\|each operation the engagement" /workspace/report.md
